pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker) public {
        vm.assume(attacker != address(this));
        vm.assume(attacker != c.owner());
        vm.prank(attacker);
        c.setOwner(address(0xdead));
        assertTrue(c.owner() != address(0xdead));
    }
}

